const item = $input.first();
const incoming = item.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : {};
const headers = incoming.headers && typeof incoming.headers === 'object' ? incoming.headers : {};
const suppliedKey = headers['x-excel-webhook-key'] ?? headers['X-Excel-Webhook-Key'] ?? '';
const expectedKey = $env.EXCEL_WEBHOOK_API_KEY || '';
const candidate = incoming.session_id ?? body.session_id;
const continuationSessionId = typeof candidate === 'string' ? candidate.trim() : '';
const hasFile = Boolean(item.binary?.file);
let parsedPayload = null;
if (typeof body.payload === 'string') {
  try { parsedPayload = JSON.parse(body.payload); } catch { parsedPayload = null; }
}
const normalizedRequest = incoming.request ?? parsedPayload?.request ?? body.request ?? (parsedPayload && typeof parsedPayload === 'object' ? parsedPayload : (body && !body.payload ? body : {}));
return [{ json: {
  ...incoming,
  request: normalizedRequest && typeof normalizedRequest === 'object' ? normalizedRequest : {},
  webhook_authorized: Boolean(expectedKey) && suppliedKey === expectedKey,
  continuation_session_id: continuationSessionId,
  missing_input: !continuationSessionId && !hasFile,
}, binary: item.binary }];

return [{ json: {
  status: 'error',
  message: "New extraction requires multipart binary field 'file' (.xlsx/.xls); a clarification continuation requires session_id.",
  next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [],
  errors: [{ code: 'MISSING_INPUT', message: 'Provide file or session_id.' }], clarification: null, meta: {},
}}];

return [{ json: {
  status: 'error',
  message: 'Unauthorized webhook request.',
  next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [],
  errors: [{ code: 'UNAUTHORIZED', message: 'Provide a valid X-Excel-Webhook-Key header.' }], clarification: null, meta: {},
}}];

const item = $input.first();
const rawRequest = typeof item.json?.request === 'string' ? item.json.request.trim() : '';
let request;
try {
  request = rawRequest ? JSON.parse(rawRequest) : {};
} catch {
  // The form should stay convenient for a human: plain text becomes prompt.
  request = { prompt: rawRequest };
}
if (!request || typeof request !== 'object' || Array.isArray(request)) request = { prompt: rawRequest };
const file = item.binary?.file;
return [{
  json: {
    request,
    request_text: rawRequest,
    continuation_session_id: '',
    missing_input: !file,
    webhook_authorized: true,
    entrypoint: 'form',
  },
  binary: file ? { file } : undefined,
}];

return [{ json: {
  status: 'error',
  message: "Form submission requires an Excel file in the 'file' field.",
  next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [],
  errors: [{ code: 'MISSING_INPUT', message: 'Attach one .xlsx or .xls file.' }], clarification: null, meta: { entrypoint: 'form' },
}}];

const item = $input.first();
const input = item.json || {};
const candidate = input.session_id;
const continuationSessionId = typeof candidate === 'string' ? candidate.trim() : '';
const hasFile = Boolean(item.binary?.file);
return [{
  json: {
    ...input,
    request: input.request ?? (input.prompt ? { prompt: input.prompt } : {}),
    clarification_response: input.clarification_response,
    continuation_session_id: continuationSessionId,
    missing_input: !continuationSessionId && !hasFile,
    webhook_authorized: true,
    entrypoint: 'subworkflow',
  },
  binary: item.binary,
}];

return [{ json: {
